package com.aoo.bcg.common.lifecycle;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ResourceScopeTest{@Test void releasesEveryResourceInReverseOrderAndPreservesFailures()throws Exception{var calls=new ArrayList<String>();var scope=new ResourceScope().defer("lock",()->calls.add("lock")).defer("mdc",()->{calls.add("mdc");throw new java.io.IOException("mdc");}).defer("temp-file",()->calls.add("temp"));var error=assertThrows(Exception.class,scope::close);assertEquals(List.of("temp","mdc","lock"),calls);assertInstanceOf(java.io.IOException.class,error.getCause());scope.close();assertEquals(3,calls.size());}}
